{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{{BUSINESS_NAME}} | Heating & Cooling Experts in {{CITY}}, {{STATE}}</title>
  <meta name="description" content="{{TAGLINE}} — Trusted HVAC installation, repair, and maintenance in {{CITY}}, {{STATE}}. Fast response, transparent pricing, and 5-star service. Call {{PHONE}}.">
  <meta name="robots" content="index,follow">
  <link rel="canonical" href="/">
  <meta name="theme-color" content="#0b5fff">
  <meta property="og:title" content="{{BUSINESS_NAME}} | Heating & Cooling Experts in {{CITY}}, {{STATE}}">
  <meta property="og:description" content="{{TAGLINE}} — Trusted HVAC installation, repair, and maintenance in {{CITY}}, {{STATE}}. Fast response, transparent pricing, and 5-star service.">
  <meta property="og:type" content="website">
  <meta property="og:url" content="/">
  <meta property="og:image" content="assets/img/hero-abstract.svg">
  <meta name="twitter:card" content="summary_large_image">
  <link rel="preload" href="assets/css/styles.css" as="style">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body>
  <a class="skip-link" href="#main">Skip to content</a>
  <div class="topbar" role="region" aria-label="Contact bar">
    <div class="container">
      <div class="meta" aria-label="Business hours">
        <span><strong>Hours:</strong> {{HOURS}}</span>
        <span class="dot" aria-hidden="true"></span>
        <span><strong>Serving:</strong> {{CITY}}, {{STATE}}</span>
      </div>
      <div class="meta">
        <a href="tel:{{PHONE}}" class="btn btn-secondary" data-dial aria-label="Call {{BUSINESS_NAME}} at {{PHONE}}">Call {{PHONE}}</a>
      </div>
    </div>
  </div>
  <header class="header">
    <div class="container nav" role="navigation" aria-label="Primary">
      <a class="brand" href="/" aria-label="{{BUSINESS_NAME}} home">
        <span class="logo-badge" aria-hidden="true">HV</span>
        <span class="name">{{BUSINESS_NAME}}</span>
      </a>
      <nav class="desktop-nav" aria-label="Main">
        <ul>
          <li><a href="/" aria-current="page">Home</a></li>
          <li><a href="services.html">Services</a></li>
          <li><a href="pricing.html">Pricing</a></li>
          <li><a href="financing.html">Financing</a></li>
          <li><a href="reviews.html">Reviews</a></li>
          <li><a href="about.html">About</a></li>
          <li><a href="contact.html">Contact</a></li>
        </ul>
      </nav>
      <div class="actions" style="display:flex;gap:8px;align-items:center">
        <a class="btn btn-secondary" href="tel:{{PHONE}}" data-dial aria-label="Call {{PHONE}}">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.79 19.79 0 0 1 2.08 4.18 2 2 0 0 1 4.06 2h3a2 2 0 0 1 2 1.72c.12.9.3 1.77.54 2.61a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.47-1.06a2 2 0 0 1 2.11-.45c.84.24 1.71.42 2.61.54A2 2 0 0 1 22 16.92z"/></svg>
          {{PHONE}}
        </a>
        <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <button class="nav-toggle" aria-expanded="false" aria-controls="mobile-menu" data-nav-toggle>
          <span aria-hidden="true">☰</span>
          <span class="sr-only">Menu</span>
        </button>
      </div>
      <div class="mobile-menu" id="mobile-menu" data-mobile-menu>
        <nav aria-label="Mobile">
          <ul>
            <li><a href="/">Home</a></li>
            <li><a href="services.html">Services</a></li>
            <li><a href="pricing.html">Pricing</a></li>
            <li><a href="financing.html">Financing</a></li>
            <li><a href="reviews.html">Reviews</a></li>
            <li><a href="about.html">About</a></li>
            <li><a href="book.html">Book</a></li>
            <li><a href="contact.html">Contact</a></li>
          </ul>
        </nav>
      </div>
    </div>
  </header>

  <main id="main">
    <section class="hero">
      <div class="container">
        <div class="hero-copy">
          <span class="hero-tag">{{TAGLINE}}</span>
          <h1>Comfort engineered for {{CITY}} homes and businesses</h1>
          <p>We design, install, and service high‑efficiency heating and cooling systems with white‑glove care. Same‑day repairs, honest diagnostics, and options that fit your budget.</p>
          <div class="hero-cta">
            <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn btn-secondary" href="tel:{{PHONE}}" data-dial>Call {{PHONE}}</a>
          </div>
          <div class="kpis" aria-label="Highlights">
            <div class="chip"><svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg>Licensed & Insured</div>
            <div class="chip"><svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>24/7 Emergency</div>
            <div class="chip"><svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><line x1="3" y1="9" x2="21" y2="9"/></svg>Same‑Day Service</div>
            <div class="chip"><svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 12v6a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h6"/><path d="M14 2h6v6"/><path d="M14 10L20 4"/></svg>Financing Available</div>
          </div>
        </div>
        <div class="hero-visual">
          <img src="assets/img/avatar-01.svg" alt="Smiling HVAC technician" class="card"/>
          <img src="assets/img/hero-abstract.svg" alt="" class="hero-blob" aria-hidden="true"/>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container stack-l">
        <div class="stack-s center">
          <span class="badge" aria-label="What we do">Core HVAC Services</span>
          <h2 class="m0">Precision service. Peak efficiency.</h2>
          <p class="m0" style="color:var(--muted)">From emergency repairs to custom installs, we do it right the first time—backed by craftsmanship and care.</p>
        </div>
        <div class="grid grid-3">
          <article class="card stack-s">
            <h3>AC Repair & Installation</h3>
            <p>Rapid diagnostics, ozone‑friendly refrigerants, and whisper‑quiet systems sized for your home.</p>
            <ul class="list mt8">
              <li><svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 6L9 17l-5-5"/></svg>Same‑day cooling fixes</li>
              <li><svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 6L9 17l-5-5"/></svg>High‑SEER replacements</li>
            </ul>
            <div><a class="btn btn-ghost" href="services.html#ac">Explore AC services →</a></div>
          </article>
          <article class="card stack-s">
            <h3>Heating & Furnaces</h3>
            <p>Smart, safe heat—gas, electric, or heat pump. Clean installs with full code compliance.</p>
            <ul class="list mt8">
              <li><svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 6L9 17l-5-5"/></svg>Efficient heat pumps</li>
              <li><svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 6L9 17l-5-5"/></svg>Furnace repair & tune‑ups</li>
            </ul>
            <div><a class="btn btn-ghost" href="services.html#heating">Explore heating →</a></div>
          </article>
          <article class="card stack-s">
            <h3>Indoor Air Quality</h3>
            <p>Breathe easy with HEPA filtration, UV purification, and humidity control tailored to your space.</p>
