            <div class="card stack-s">
              <h3 class="m0">$0 down</h3>
              <p class="m0">With approved credit on qualifying systems.</p>
            </div>
            <div class="card stack-s">
              <h3 class="m0">Fast decisions</h3>
              <p class="m0">Apply in minutes, get options instantly.</p>
            </div>
            <div class="card stack-s">
              <h3 class="m0">No penalty</h3>
              <p class="m0">Pay off early anytime without fees.</p>
            </div>
          </div>
          <div class="card stack-m">
            <h2 class="m0">How it works</h2>
            <ol class="list">
              <li>Choose your system and comfort level with our advisor.</li>
              <li>Apply from your phone—secure and simple.</li>
              <li>Pick your monthly plan and schedule installation.</li>
            </ol>
            <div class="hero-cta"><a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">Start application</a><a class="btn btn-secondary" href="pricing.html">See pricing</a></div>
          </div>
        </div>
        <aside class="stack-l" aria-label="FAQs">
